#!/usr/bin/env bash
#
# Regenerate sitemap.xml on main and, if it changed, commit it as the bot.
#
# Why this exists: lastmod is each page's last *commit* date. A sitemap committed
# together with the pages it describes is therefore stale by construction (the
# page has no new commit yet), and `generate-sitemap.sh --check` goes red after
# every hand edit. Regenerating it from the history that now exists is the fix.
#
# This must not loop. Three independent things guarantee it:
#
#   - the workflow only fires for pushes that touch .html files, and this
#     commit touches sitemap.xml alone
#   - pushes made with GITHUB_TOKEN do not start workflows at all
#   - it is idempotent: this commit changes no page, so no page's last-commit
#     date moves, and a second run finds nothing to do
#
# Other writers (drip-publish.yml, a human push) can move main while we run.
# On a rejected push we drop our own commit, fast-forward, and regenerate on top
# of the new tip. Rebasing instead would conflict, because drip rewrites
# sitemap.xml too.
#
# Refuses to run on a dirty tree or off main: the retry path uses `git reset
# --hard` to drop its own rejected commit, and nothing else.

set -euo pipefail

BRANCH="main"
MAX_ATTEMPTS=3

say() { echo "==> $*"; }

summary() {
  echo "$*"
  [[ -n "${GITHUB_STEP_SUMMARY:-}" ]] && echo "$*" >> "$GITHUB_STEP_SUMMARY"
  return 0
}

if [[ "$(git rev-parse --abbrev-ref HEAD)" != "$BRANCH" ]]; then
  echo "sitemap-refresh: must run on $BRANCH, not $(git rev-parse --abbrev-ref HEAD)." >&2
  exit 2
fi

if [[ -n "$(git status --porcelain)" ]]; then
  echo "sitemap-refresh: working tree is not clean; refusing to run." >&2
  git --no-pager status --short >&2
  exit 2
fi

# Scoped to the commit via -c, never written to .git/config (same reasoning as
# drip-publish.sh).
bot_identity=(-c user.name="github-actions[bot]" -c user.email="41898282+github-actions[bot]@users.noreply.github.com")

pushed=0
for attempt in $(seq 1 "$MAX_ATTEMPTS"); do
  say "Regenerating sitemap.xml (attempt $attempt/$MAX_ATTEMPTS)"
  bash scripts/generate-sitemap.sh

  if git diff --quiet -- sitemap.xml; then
    if [[ "$pushed" -eq 0 && "$attempt" -eq 1 ]]; then
      summary "sitemap.xml is already up to date; nothing to commit."
    else
      summary "sitemap.xml was refreshed by a concurrent writer; nothing left to commit."
    fi
    break
  fi

  git add -- sitemap.xml
  git "${bot_identity[@]}" commit \
    -m "Refresh sitemap.xml lastmod dates" \
    -m "Regenerated by scripts/generate-sitemap.sh from the commit history. Automated by .github/workflows/sitemap-refresh.yml."

  if git push origin "HEAD:$BRANCH"; then
    summary "Committed and pushed a refreshed sitemap.xml."
    pushed=1
    break
  fi

  if [[ "$attempt" -eq "$MAX_ATTEMPTS" ]]; then
    summary "FAILED: push rejected $MAX_ATTEMPTS times; sitemap.xml was not refreshed."
    exit 1
  fi

  say "Push rejected: $BRANCH moved. Dropping our commit and regenerating on the new tip."
  git reset --hard HEAD~1
  git fetch origin "$BRANCH"
  git merge --ff-only "origin/$BRANCH"
done

# Whatever happened above, the tip we leave behind must satisfy the check.
bash scripts/generate-sitemap.sh --check
